import{_ as t,o as a,c as o,a5 as c}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Plan — Deactivate Account","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-9-deactivate-account/plan.md","filePath":"feature/authentication/3-2-9-deactivate-account/plan.md"}'),i={name:"feature/authentication/3-2-9-deactivate-account/plan.md"};function n(s,e,l,d,r,h){return a(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="plan-—-deactivate-account" tabindex="-1">Plan — Deactivate Account <a class="header-anchor" href="#plan-—-deactivate-account" aria-label="Permalink to &quot;Plan — Deactivate Account&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> — Soft-delete account, 2 flow xác thực (password / OTP), chặn nếu là Owner duy nhất Agency active.</p><h2 id="quyet-đinh-cau-hoi-mo-spec-edge-cases" tabindex="-1">Quyết định câu hỏi mở (spec Edge Cases) <a class="header-anchor" href="#quyet-đinh-cau-hoi-mo-spec-edge-cases" aria-label="Permalink to &quot;Quyết định câu hỏi mở (spec Edge Cases)&quot;">​</a></h2><p>Spec để mở: &quot;User là Owner Agency active → deactivate thì Agency xử lý sao?&quot; — <strong>Chốt với Trung: Chặn, bắt transfer trước.</strong> Áp dụng chung cho cả 2 flow.</p><p>Spec để mở: &quot;User OAuth-only (không có password) muốn deactivate thì sao, vì không thể verify password?&quot; — <strong>Chốt: thêm flow OTP qua email (2026-09-23).</strong></p><h2 id="ky-thuat" tabindex="-1">Kỹ thuật <a class="header-anchor" href="#ky-thuat" aria-label="Permalink to &quot;Kỹ thuật&quot;">​</a></h2><ul><li><code>DeactivateRequest(password, otpCode)</code> — cả 2 field optional, không validation annotation.</li><li><code>POST /api/v1/auth/deactivate/send-otp</code> (Bearer, không body) — sinh OTP 6 số, lưu Redis <code>otp:deactivate:{userId}</code> TTL 10 phút, gửi email qua <code>mailService.sendOtpEmail</code>.</li><li><code>POST /api/v1/auth/deactivate { password?, otpCode? }</code> (Bearer + <code>refreshToken</code> cookie): <ul><li><code>user.passwordHash != null</code> → verify <code>password</code> (bcrypt) → sai → 400 <code>WRONG_CURRENT_PASSWORD</code>.</li><li><code>user.passwordHash == null</code> → verify <code>otpCode</code> với Redis key → sai/thiếu/hết hạn → 400 <code>OTP_INVALID</code> → đúng thì xóa key.</li></ul></li><li><code>agencyRepository.findByOwnerId(userId)</code> → có Agency <code>EntityStatus.ACTIVE</code>? → 409 <code>AGENCY_OWNERSHIP_ACTIVE</code>.</li><li>Không có → <code>setStatus(UserStatus.DEACTIVATED)</code> (soft delete), KHÔNG xóa cứng.</li><li><strong>MỚI</strong>: Sau khi save status, blacklist accessToken + refreshToken (nếu có) qua <code>jwtUtil.blacklistToken()</code> — best-effort, bắt <code>JwtException</code> bỏ qua nếu token thiếu/hỏng. Cắt session ngay lập tức, không đợi refresh lần sau.</li><li>Sau deactivate, login/refresh → <code>checkStatus</code> → 403 <code>ACCOUNT_DEACTIVATED</code> (backup, đã có blacklist nên không còn là cơ chế cắt session duy nhất).</li></ul><h2 id="luong" tabindex="-1">Luồng <a class="header-anchor" href="#luong" aria-label="Permalink to &quot;Luồng&quot;">​</a></h2><p><strong>Flow A (có password):</strong></p><ol><li>Auth → userId.</li><li>Verify password → sai → 400.</li><li>Check Agency active (owner) → có → 409.</li><li><code>status=DEACTIVATED</code> → blacklist accessToken + refreshToken → 200.</li></ol><p><strong>Flow B (OAuth-only):</strong></p><ol><li>Auth → userId → gọi <code>send-otp</code> → sinh OTP, lưu Redis, gửi email → 200.</li><li>Client gọi <code>deactivate { otpCode }</code> → auth → userId.</li><li>Verify OTP với Redis → sai/thiếu/hết hạn → 400 → đúng thì xóa key.</li><li>Check Agency active (owner) → có → 409.</li><li><code>status=DEACTIVATED</code> → blacklist accessToken + refreshToken → 200.</li></ol><h2 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h2><ul><li><code>users.status</code> → <code>DEACTIVATED</code> (enum value).</li><li><code>users.password_hash</code> — dùng để phân nhánh flow (null → OTP, not null → password).</li><li><code>agencies.owner_id</code>, <code>agencies.status</code>.</li><li>Redis key <code>otp:deactivate:{userId}</code> — TTL 10 phút, giá trị OTP 6 số.</li></ul><h2 id="rui-ro" tabindex="-1">Rủi ro <a class="header-anchor" href="#rui-ro" aria-label="Permalink to &quot;Rủi ro&quot;">​</a></h2><ul><li>Không xóa cứng (giữ Agency/Workspace membership). User muốn khôi phục → nhờ Admin (ngoài scope).</li><li>Flow B: nếu mailService lỗi (send-otp thất bại), user OAuth-only không có cách nào khác để deactivate — cần theo dõi log lỗi gửi mail.</li><li>UI/UX 2 bước (send-otp rồi mới nhập OTP) cho user OAuth-only — <strong>cần FE xác nhận thiết kế</strong> (xem spec.md mục 4).</li></ul>',16)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
